{
  "scenario": "Приём инкассаторской сумки",
  "timeline": [
    {
      "t": 0.0,
      "event": "Кассир сидит за рабочим столом, в помещении никого нет, дверь закрыта."
    },
    {
      "t": 2.0,
      "event": "Второй работник (по внешнему виду — инкассатор) подходит к двери кассы, в руках у него зелёная сумка."
    },
    {
      "t": 5.0,
      "event": "Второй работник открывает дверь и входит в кассовое помещение."
    },
    {
      "t": 8.5,
      "event": "Второй работник передаёт кассиру документ, кассир берёт его в руки."
    },
    {
      "t": 10.0,
      "event": "Кассир рассматривает документ, второй работник стоит у стола."
    },
    {
      "t": 15.0,
      "event": "Кассир возвращает документ второму работнику."
    },
    {
      "t": 16.0,
      "event": "Второй работник кладёт зелёную сумку на стол перед кассиром."
    },
    {
      "t": 17.0,
      "event": "Кассир берёт сумку и начинает осматривать её (вероятно, проверяет пломбу или шов)."
    },
    {
      "t": 22.0,
      "event": "Кассир продолжает держать и осматривать сумку, второй работник стоит рядом."
    }
  ],
